CREATE MATERIALIZED VIEW candidate.report AS SELECT COALESCE(t.building, 'Unknown') AS building, COUNT(*) AS total_tickets, COUNT(*) FILTER (WHERE t.status IN ('resolved', 'closed')) AS terminal_tickets, COUNT(*) FILTER (WHERE t.status IN ('open', 'in_progress', 'pending_vendor', 'escalated')) AS unresolved_tickets, COUNT(*) FILTER (WHERE t.status IS NULL OR t.status NOT IN ('open', 'in_progress', 'pending_vendor', 'escalated', 'resolved', 'closed')) AS unknown_status_tickets, COUNT(*) FILTER (WHERE t.status IN ('open', 'in_progress', 'pending_vendor', 'escalated') AND lower(btrim(t.priority)) = 'critical') AS critical_unresolved_tickets, COUNT(*) FILTER (WHERE t.cost IS NOT NULL AND t.cost >= 0) AS tickets_with_recorded_cost, SUM(t.cost) FILTER (WHERE t.cost IS NOT NULL AND t.cost >= 0) AS total_recorded_cost, AVG(t.cost) FILTER (WHERE t.cost IS NOT NULL AND t.cost >= 0) AS average_recorded_cost, 100.0 * COUNT(*) FILTER (WHERE t.cost IS NOT NULL AND t.cost >= 0) / NULLIF(COUNT(*), 0) AS cost_coverage_pct, 100.0 * COUNT(*) FILTER (WHERE t.status IN ('resolved', 'closed')) / NULLIF(COUNT(*) FILTER (WHERE t.status IN ('open', 'in_progress', 'pending_vendor', 'escalated', 'resolved', 'closed')), 0) AS terminal_rate_pct FROM silver.tickets AS t GROUP BY COALESCE(t.building, 'Unknown')